"use client";

import { useState, useEffect, useMemo } from "react";
import axios from "axios";
import { Eye, Camera, AlertCircle, CheckCircle, Loader2, RefreshCw, X } from "lucide-react";
import Layout from "../Layout";

export default function PreviousMeals() {
  const [meals, setMeals] = useState([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");
  const [uploadingMealId, setUploadingMealId] = useState(null);
  const [selectedPhoto, setSelectedPhoto] = useState(null);
  const [searchQuery, setSearchQuery] = useState("");
  const [filterYear, setFilterYear] = useState(null);
  const [filterMonth, setFilterMonth] = useState(null);
  const [filterDay, setFilterDay] = useState(null);

  useEffect(() => {
    fetchPreviousMeals();
  }, []);

  const fetchPreviousMeals = async () => {
    setIsLoading(true);
    setError("");
    setSuccess("");
    setSearchQuery("");
    setFilterYear(null);
    setFilterMonth(null);
    setFilterDay(null);
    const token = localStorage.getItem("token");

    if (!token) {
      setError("Vous devez être connecté pour accéder aux repas.");
      setIsLoading(false);
      return;
    }

    try {
      const today = new Date();
      today.setHours(0, 0, 0, 0);
      const response = await axios.get(`${process.env.REACT_APP_API_URL}/api/meals`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      const previousMeals = response.data.filter(
        (meal) => new Date(meal.date) < today
      );
      setMeals(previousMeals);
    } catch (err) {
      setError(
        "Erreur lors de la récupération des repas précédents : " +
          (err.response?.data?.message || err.message)
      );
    } finally {
      setIsLoading(false);
    }
  };

  const handlePhotoUpload = async (e, mealId) => {
    const file = e.target.files[0];
    if (!file) return;

    setError("");
    setSuccess("");
    setUploadingMealId(mealId);

    const token = localStorage.getItem("token");
    const formData = new FormData();
    formData.append("mealPhoto", file);

    try {
      const response = await axios.put(
        `${process.env.REACT_APP_API_URL}/api/meals/${mealId}`,
        formData,
        {
          headers: {
            Authorization: `Bearer ${token}`,
            "Content-Type": "multipart/form-data",
          },
        }
      );
      setMeals((prev) =>
        prev.map((meal) =>
          meal._id === mealId ? { ...meal, mealPhoto: response.data.data.mealPhoto } : meal
        )
      );
      setSuccess("Photo du repas installée avec succès !");
    } catch (err) {
      setError(
        "Erreur lors de l'installation de la photo : " +
          (err.response?.data?.message || err.message)
      );
    } finally {
      setUploadingMealId(null);
    }
  };

  const openPhotoModal = (mealPhoto) => {
    setSelectedPhoto(mealPhoto);
  };

  const closePhotoModal = () => {
    setSelectedPhoto(null);
  };

  // Generate filter options
  const uniqueYears = useMemo(() => {
    return [...new Set(meals.map(meal => new Date(meal.date).getFullYear()))].sort((a, b) => a - b);
  }, [meals]);

  const months = [
    { value: 1, label: "Janvier" },
    { value: 2, label: "Février" },
    { value: 3, label: "Mars" },
    { value: 4, label: "Avril" },
    { value: 5, label: "Mai" },
    { value: 6, label: "Juin" },
    { value: 7, label: "Juillet" },
    { value: 8, label: "Août" },
    { value: 9, label: "Septembre" },
    { value: 10, label: "Octobre" },
    { value: 11, label: "Novembre" },
    { value: 12, label: "Décembre" },
  ];

  const getDaysInMonth = (year, month) => {
    if (!year || !month) return Array.from({ length: 31 }, (_, i) => i + 1);
    return Array.from(
      { length: new Date(year, month, 0).getDate() },
      (_, i) => i + 1
    );
  };

  const days = useMemo(() => getDaysInMonth(filterYear, filterMonth), [filterYear, filterMonth]);

  // Filter meals
  const filteredMeals = useMemo(() => {
    return meals.filter((meal) => {
      const mealDate = new Date(meal.date);
      const yearMatch = !filterYear || mealDate.getFullYear() === parseInt(filterYear);
      const monthMatch = !filterMonth || mealDate.getMonth() + 1 === parseInt(filterMonth);
      const dayMatch = !filterDay || mealDate.getDate() === parseInt(filterDay);
      const nameMatch = !searchQuery || meal.mealName.toLowerCase().includes(searchQuery.toLowerCase());
      return yearMatch && monthMatch && dayMatch && nameMatch;
    });
  }, [meals, searchQuery, filterYear, filterMonth, filterDay]);

  return (
    <Layout>
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        <div className="bg-white rounded-2xl shadow-xl overflow-hidden border border-[#C8A45D/30]/50">
          <div className="bg-gradient-to-r from-[#00717F] to-[#C8A45D] text-white p-6">
            <div className="flex justify-between items-center">
              <div>
                <h2 className="text-2xl font-bold tracking-tight">Repas Précédents</h2>
                <p className="text-white/80 mt-1 text-sm">
                  Liste des repas dont la date est antérieure à aujourd'hui
                </p>
              </div>
              <button
                onClick={fetchPreviousMeals}
                className="flex items-center gap-2 text-white hover:text-[#C8A45D/20] transition-colors duration-200"
              >
                <RefreshCw className="h-5 w-5" />
                <span>Rafraîchir</span>
              </button>
            </div>
          </div>

          {(error || success) && (
            <div
              className={`p-4 ${error ? "bg-red-50" : "bg-green-50"} border-l-4 ${
                error ? "border-red-500" : "border-green-500"
              } flex items-center gap-3`}
            >
              {error ? (
                <AlertCircle className="h-5 w-5 text-red-500" />
              ) : (
                <CheckCircle className="h-5 w-5 text-green-500" />
              )}
              <p className={`text-sm ${error ? "text-red-700" : "text-green-700"}`}>
                {error || success}
              </p>
            </div>
          )}

          <div className="p-6">
            {/* Search and Filter Controls */}
            <div className="mb-6 flex flex-col sm:flex-row gap-4">
              <div className="flex-1">
                <label htmlFor="search" className="block text-sm font-medium text-gray-700 mb-1">
                  Rechercher par nom
                </label>
                <input
                  id="search"
                  type="text"
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  placeholder="Entrez le nom du repas..."
                  className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-[#00717F] text-sm"
                />
              </div>
              <div className="flex gap-4">
                <div>
                  <label htmlFor="year" className="block text-sm font-medium text-gray-700 mb-1">
                    Année
                  </label>
                  <select
                    id="year"
                    value={filterYear || ""}
                    onChange={(e) => setFilterYear(e.target.value || null)}
                    className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-[#00717F] text-sm"
                  >
                    <option value="">Tous</option>
                    {uniqueYears.map((year) => (
                      <option key={year} value={year}>
                        {year}
                      </option>
                    ))}
                  </select>
                </div>
                <div>
                  <label htmlFor="month" className="block text-sm font-medium text-gray-700 mb-1">
                    Mois
                  </label>
                  <select
                    id="month"
                    value={filterMonth || ""}
                    onChange={(e) => {
                      setFilterMonth(e.target.value || null);
                      setFilterDay(null); // Reset day when month changes
                    }}
                    className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-[#00717F] text-sm"
                  >
                    <option value="">Tous</option>
                    {months.map((month) => (
                      <option key={month.value} value={month.value}>
                        {month.label}
                      </option>
                    ))}
                  </select>
                </div>
                <div>
                  <label htmlFor="day" className="block text-sm font-medium text-gray-700 mb-1">
                    Jour
                  </label>
                  <select
                    id="day"
                    value={filterDay || ""}
                    onChange={(e) => setFilterDay(e.target.value || null)}
                    className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-[#00717F] text-sm"
                  >
                    <option value="">Tous</option>
                    {days.map((day) => (
                      <option key={day} value={day}>
                        {day}
                      </option>
                    ))}
                  </select>
                </div>
              </div>
            </div>

            {isLoading ? (
              <div className="flex justify-center items-center h-64">
                <div className="flex flex-col items-center gap-2">
                  <Loader2 className="h-10 w-10 text-[#00717F] animate-spin" />
                  <p className="text-[#00717F] text-sm font-medium">Chargement des repas...</p>
                </div>
              </div>
            ) : filteredMeals.length === 0 ? (
              <p className="text-gray-500 text-center">Aucun repas trouvé.</p>
            ) : (
              <div className="overflow-x-auto">
                <table className="min-w-full divide-y divide-[#C8A45D/30]">
                  <thead>
                    <tr className="bg-[#F5F6FA] text-[#00717F]">
                      <th className="py-3.5 px-4 text-left text-xs font-semibold uppercase tracking-wider rounded-tl-lg">
                        Nom du Repas
                      </th>
                      <th className="py-3.5 px-4 text-left text-xs font-semibold uppercase tracking-wider">
                        Type
                      </th>
                      <th className="py-3.5 px-4 text-left text-xs font-semibold uppercase tracking-wider">
                        Date
                      </th>
                      <th className="py-3.5 px-4 text-left text-xs font-semibold uppercase tracking-wider">
                        Prix
                      </th>
                      <th className="py-3.5 px-4 text-left text-xs font-semibold uppercase tracking-wider rounded-tr-lg">
                        Actions
                      </th>
                    </tr>
                  </thead>
                  <tbody className="bg-white divide-y divide-[#C8A45D/30]/30">
                    {filteredMeals.map((meal) => (
                      <tr
                        key={meal._id}
                        className="hover:bg-[#F5F6FA]/30 transition-colors duration-150"
                      >
                        <td className="py-4 px-4 text-sm text-gray-700">
                          {meal.mealName}
                        </td>
                        <td className="py-4 px-4 text-sm text-gray-700">
                          {meal.type === "Breakfast"
                            ? "Petit-déjeuner"
                            : meal.type === "Lunch"
                            ? "Déjeuner"
                            : "Dîner"}
                        </td>
                        <td className="py-4 px-4 text-sm text-gray-700">
                          {new Date(meal.date).toLocaleDateString("fr-FR")}
                        </td>
                        <td className="py-4 px-4 text-sm text-gray-700">
                          {meal.priceOfMeal} DH
                        </td>
                        <td className="py-4 px-4 text-sm flex gap-2">
                          <button
                            onClick={() => openPhotoModal(meal.mealPhoto)}
                            disabled={!meal.mealPhoto}
                            className={`inline-flex items-center gap-2 px-3 py-1.5 rounded-md text-white font-medium transition-colors ${
                              meal.mealPhoto
                                ? "bg-blue-600 hover:bg-blue-700"
                                : "bg-gray-400 cursor-not-allowed"
                            }`}
                            aria-label="Voir la photo du repas"
                          >
                            <Eye className="h-4 w-4" />
                            Voir Photo
                          </button>
                          <label
                            htmlFor={`photo-upload-${meal._id}`}
                            className="cursor-pointer inline-flex items-center gap-2 px-3 py-1.5 bg-[#00717F] text-white rounded-md hover:bg-[#00717F]/90 transition-colors"
                          >
                            <Camera className="h-4 w-4" />
                            Installer Photo
                            <input
                              id={`photo-upload-${meal._id}`}
                              type="file"
                              accept="image/*"
                              className="hidden"
                              onChange={(e) => handlePhotoUpload(e, meal._id)}
                              disabled={uploadingMealId === meal._id}
                            />
                          </label>
                          {uploadingMealId === meal._id && (
                            <Loader2 className="inline-block ml-2 h-4 w-4 text-[#00717F] animate-spin" />
                          )}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </div>
        </div>
      </div>

      {selectedPhoto && (
        <div className="fixed inset-0 bg-black/80 backdrop-blur-md flex justify-center items-center z-50 p-4 md:p-8">
          <div className="max-w-4xl w-full bg-white rounded-2xl shadow-2xl overflow-hidden animate-in zoom-in-95 duration-300">
            <div className="relative">
              <button
                onClick={closePhotoModal}
                className="absolute right-4 top-4 rounded-full p-2 bg-black/50 text-white hover:bg-black/70 transition-colors z-10"
                aria-label="Fermer"
              >
                <X className="h-5 w-5" />
              </button>

              <div className="p-0">
                <img
                  src={`${process.env.REACT_APP_API_URL}${selectedPhoto}`}
                  alt="Photo du repas"
                  className="w-full h-auto max-h-[80vh] object-contain"
                />
              </div>

              <div className="p-4 bg-zinc-50 border-t flex justify-end">
                <button
                  onClick={closePhotoModal}
                  className="px-5 py-2.5 bg-white border border-zinc-300 rounded-lg text-zinc-700 hover:bg-zinc-50 transition-colors text-sm font-medium"
                >
                  Fermer
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </Layout>
  );
}
